"""Undoes git/gitpython unicode encoding."""
def git_unicode_unescape(s: str, encoding: str = "utf-8") -> str {
    if (s is None) {
        return "";
    }
    if s.startswith('"') {
        return s.strip('"').encode("latin1").decode("unicode-escape").encode(
            "latin1"
        ).decode(
            encoding
        );
    }
    return s;
}

